import type { QueueItem } from '@api/api-types';

const isQueueItem = (item: unknown): item is QueueItem =>
  Boolean(
    item &&
      typeof item === 'object' &&
      'id' in item &&
      'doctor' in item &&
      'clinic' in item &&
      'type' in item,
  );

export const selectRecommendedGpProvider = (
  response: unknown,
): QueueItem | undefined => {
  if (
    !response ||
    typeof response !== 'object' ||
    !('success' in response) ||
    response.success !== true ||
    !('data' in response) ||
    !Array.isArray(response.data) ||
    response.data.length === 0
  ) {
    return undefined;
  }

  const firstProvider = response.data[0];

  return isQueueItem(firstProvider) ? firstProvider : undefined;
};

