import type { QueueItem } from '../src/api/api-types';
import { selectRecommendedGpProvider } from '../src/screens/doctor-detail-screen/recommended-gp';

const createProvider = (id: string): QueueItem => ({
  id,
  isOnline: true,
  queuePosition: 1,
  queueExpectedTime: null,
  type: ['tc-queuing'],
  clinic: {
    name: `Clinic ${id}`,
    country: 'China',
    region: 'China',
    area: '',
    district: '',
    address: '',
    coordinates: {
      lat: 0,
      lng: 0,
    },
  },
  doctor: {
    id: `doctor-${id}`,
    name: `Doctor ${id}`,
    type: 'General Practice',
    specialties: ['General Practice'],
    specialtyIds: ['general-practice'],
  },
  hasValidContract: true,
});

describe('selectRecommendedGpProvider', () => {
  test('uses the first provider when the recommended GP response has multiple doctors', () => {
    const firstProvider = createProvider('provider-1');
    const secondProvider = createProvider('provider-2');

    expect(
      selectRecommendedGpProvider({
        success: true,
        data: [firstProvider, secondProvider],
      }),
    ).toBe(firstProvider);
  });

  test('uses the only provider when the recommended GP response has one doctor', () => {
    const provider = createProvider('provider-1');

    expect(
      selectRecommendedGpProvider({
        success: true,
        data: [provider],
      }),
    ).toBe(provider);
  });

  test('returns no provider when the recommended GP response is empty or unsuccessful', () => {
    expect(
      selectRecommendedGpProvider({
        success: true,
        data: [],
      }),
    ).toBeUndefined();
    expect(
      selectRecommendedGpProvider({
        success: false,
        data: [createProvider('provider-1')],
      }),
    ).toBeUndefined();
  });
});

