const ts = require('typescript');
const path = require('path');
const configPath = path.resolve('tsconfig.json');
const read = ts.readConfigFile(configPath, ts.sys.readFile);
const host = ts.createCompilerHost({});
const parsed = ts.parseJsonConfigFileContent(read.config, ts.sys, path.dirname(configPath));
parsed.options.module = ts.ModuleKind.ESNext;
parsed.options.noEmit = true;
const program = ts.createProgram({ rootNames: parsed.fileNames, options: parsed.options });
const targets = [
  'src/assets/svg/drawer-activate-icon.tsx',
  'src/assets/svg/drawer-heals-plans-icon.tsx',
  'src/assets/svg/drawer-medical-records-icon.tsx',
  'src/assets/svg/drawer-signout-icon.tsx',
  'src/assets/svg/drawer-transactions-icon.tsx',
  'src/components/custom-drawer/custom-drawer-content.styles.ts',
  'src/components/custom-drawer/custom-drawer-content.tsx',
  'src/components/custom-drawer/custom-drawer.styles.ts',
  'src/components/custom-drawer/custom-drawer.tsx',
  'src/components/drawer-row-item/drawer-row-item.styles.ts',
  'src/components/drawer-row-item/drawer-row-item.tsx',
].map((f) => path.resolve(f));
const interesting = new Set(targets);
const format = (d) => {
  const file = d.file ? path.relative(process.cwd(), d.file.fileName) : '<nofile>';
  const pos = d.file && d.start != null ? d.file.getLineAndCharacterOfPosition(d.start) : null;
  return {
    file,
    line: pos ? pos.line + 1 : null,
    code: 'TS' + d.code,
    category: ts.DiagnosticCategory[d.category],
    message: ts.flattenDiagnosticMessageText(d.messageText, '\n'),
  };
};
const all = [
  ...program.getSemanticDiagnostics(),
  ...program.getSyntacticDiagnostics(),
  ...program.getOptionsDiagnostics(),
  ...program.getGlobalDiagnostics(),
];
const suggestion = [];
for (const file of targets) {
  const sf = program.getSourceFile(file);
  if (!sf) {
    suggestion.push({ file: path.relative(process.cwd(), file), missing: true });
    continue;
  }
  for (const d of program.getSuggestionDiagnostics(sf)) suggestion.push(format(d));
}
const related = all.filter((d) => d.file && interesting.has(path.resolve(d.file.fileName))).map(format);
const configErrors = all.filter((d) => !d.file).map(format);
console.log(JSON.stringify({
  fileCount: parsed.fileNames.length,
  related,
  suggestion,
  configErrors: configErrors.slice(0, 20),
  configErrorCount: configErrors.length,
}, null, 2));
EOF
